import re,json,html
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';js=(r/'docs/replica/source/original.js').read_text();icons=dict(re.findall(r"(\w+):'([^']*)'",re.search(r'const icons=\{(.*?)\};',js).group(1)))
(o/'tablemappingrow-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
svg=lambda n:'<svg class="svg" viewBox="0 0 24 24" aria-hidden="true">'+icons[n]+'</svg>'
parts=['<!doctype html><meta charset="utf-8"><title>TableMappingRow · original isolation</title><link rel="stylesheet" href="tablemappingrow-original.css"><style>body{min-width:1400px}.fixture{position:absolute}.fixture *{transition:none!important;animation:none!important}.fixture tr.force-hover{background:#3a3c44}.fixture-target-text{display:block}</style>'];cases=[]
for lang in ['ko','en']:
 for w in [610,858,1058]:
  for manual in [False,True]:
   index=len(cases)//4;parts.append(f'<section class="table-shell fixture" style="left:30px;top:{30+index*420}px;width:{w+2}px"><table><thead><tr>'+''.join('<th>'+x+'</th>'for x in (['원본 테이블','대상 테이블','대응 방식','']if lang=='ko'else['Source table','Target table','Matching','']))+'</tr></thead><tbody>')
   for i,name in enumerate(['demo.customers','demo.orders','demo.line_items','demo.customers']):
    selected=i%2==0;hover=i>=2;last=i==3;target='archive.orders' if manual and i==0 else name;is_manual=target!=name;method=('수동 · 이름 차이 유지'if lang=='ko'else'Manual · Name difference retained')if is_manual else('동일 이름'if lang=='ko'else'Same name');label='대응 변경'if lang=='ko'else'Change match';id=f'{lang}-{w}-{int(manual)}-{i}'
    cases.append(dict(id=id,lang=lang,source=name,target=target,selected=selected,manual=is_manual,method=method,button=label,hover=hover,last=last,width=w))
    parts.append(f'<tr data-id="{id}" class="{"force-hover"if hover else""}"><td><label class="table-choice"><input type="checkbox" data-table="{id}" {"checked"if selected else""}><span class="mono">{name}</span></label></td><td class="mono"><span class="fixture-target-text">{target}</span></td><td><span class="match-method {"manual"if is_manual else""}">{svg("swap"if is_manual else"check")}<span class="fixture-method-text">{method}</span></span></td><td><button class="btn quiet" type="button">{svg("swap")}<span>{label}</span></button></td></tr>')
   parts.append('</tbody></table></section>')
# Wrapping method text has a span solely for actual computed line-box measurement; source text node is anonymous flex item.
parts.append('''<button id="table-row-record" style="position:fixed;right:20px;top:20px">Record TableMappingRow</button><script>
function measurements(){return [...document.querySelectorAll('tr[data-id]')].map(e=>{const r=e.getBoundingClientRect();const box=x=>{const q=x.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}};const cols=[...e.querySelectorAll('td')].map(x=>x.getBoundingClientRect().width);const choice=e.querySelector('label'),source=choice.querySelector('span'),method=e.querySelector('.match-method'),button=e.querySelector('button');return{id:e.dataset.id,width:r.width,height:r.height,columns:cols,choice:box(choice),checkbox:box(choice.querySelector('input')),source:box(source),target:box(e.querySelector(".fixture-target-text")),method:box(method),methodIcon:box(method.querySelector('svg')),methodText:box(method.querySelector('span')),button:box(button),buttonText:box(button.querySelector('span')),buttonIcon:box(button.querySelector('svg')),style:{background:getComputedStyle(e).backgroundColor,methodColor:getComputedStyle(method).color,choiceCursor:getComputedStyle(choice).cursor}}})};
document.getElementById('table-row-record').onclick=async()=>{const v={dpr:devicePixelRatio,rows:measurements()};const result=await fetch('/evidence/source-tablemappingrow.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});if(!result.ok)throw Error('Example record failed');document.getElementById('table-row-record').textContent='Rows recorded';};</script>''')
